const { ApolloServer, gql } = require('apollo-server-express');
const express = require('express');
const jwt = require('jsonwebtoken');
const fs = require('fs');

// Load RSA public key for JWT verification
const PUBLIC_KEY = fs.readFileSync('/app/keys/rsa_public.pem', 'utf8');

const typeDefs = gql`
  type User {
    id: ID!
    email: String!
    role: String!
    apiKeys: [String]
  }

  type Query {
    me: User
    users: [User]
    adminPanel: String
  }

  type Mutation {
    refreshToken(token: String!): String
  }
`;

const users = [
  { id: '1', email: 'admin@corp.internal', role: 'admin', apiKeys: ['sk-prod-9x8f'] },
  { id: '2', email: 'user@corp.internal', role: 'viewer', apiKeys: [] },
];

function verifyToken(token) {
  // Decode header to determine algorithm
  const decoded = jwt.decode(token, { complete: true });
  if (!decoded) throw new Error('Invalid token');

  const algorithm = decoded.header.alg;

  // Verify with the public key using the algorithm specified in the token header
  // This supports both RS256 tokens from our IdP and legacy HS256 service tokens
  const options = { algorithms: [algorithm] };

  try {
    return jwt.verify(token, PUBLIC_KEY, options);
  } catch (err) {
    // Fallback: try verification treating key as symmetric secret for HS256 compat
    if (algorithm === 'HS256') {
      return jwt.verify(token, PUBLIC_KEY, { algorithms: ['HS256'] });
    }
    throw err;
  }
}

const resolvers = {
  Query: {
    me: (_, __, context) => {
      if (!context.user) throw new Error('Not authenticated');
      return users.find(u => u.id === context.user.sub);
    },
    users: (_, __, context) => {
      if (!context.user || context.user.role !== 'admin') throw new Error('Forbidden');
      return users;
    },
    adminPanel: (_, __, context) => {
      if (!context.user || context.user.role !== 'admin') throw new Error('Forbidden');
      return 'Admin secrets: DB_PASSWORD=hunter2, AWS_KEY=AKIA...';
    },
  },
  Mutation: {
    refreshToken: (_, { token }) => {
      const payload = verifyToken(token);
      // Issue new token (simplified)
      return jwt.sign({ sub: payload.sub, role: payload.role }, PUBLIC_KEY, { algorithm: 'HS256', expiresIn: '1h' });
    },
  },
};

async function startServer() {
  const app = express();

  // Trust proxy headers for logging (behind LB)
  app.set('trust proxy', true);

  // Health check endpoint (no auth)
  app.get('/health', (req, res) => res.json({ status: 'ok' }));

  const server = new ApolloServer({
    typeDefs,
    resolvers,
    context: ({ req }) => {
      const authHeader = req.headers.authorization;
      if (!authHeader) return {};

      const token = authHeader.replace('Bearer ', '');
      try {
        const user = verifyToken(token);
        return { user };
      } catch (e) {
        console.warn(`Auth failed from ${req.ip}: ${e.message}`);
        return {};
      }
    },
    introspection: true,
    playground: true,
  });

  await server.start();
  server.applyMiddleware({ app, path: '/graphql' });

  app.listen(4000, '0.0.0.0', () => {
    console.log('GraphQL server running on port 4000');
  });
}

startServer();
